local _, addonTable = ...

local gossip = { -- [npc_id] = { [hash]=translation, ..., [!code]={...} (optional) }, ... }
[16816] = { -- Echo of Medivh
-- Now that you have bested me, test your skills against each other! Take control of either king to begin play.
[3966870133] = [===[Тепер, коли ви здолали мене, випробуйте свою майстерність одне проти одного! Торкніться будь-якого короля, щоб почати гру.]===],
-- Please reset the chess board, we would like to play again.
[506398006] = [===[Будь ласка, віднови шахову дошку — ми хотіли б зіграти ще раз.]===],
-- To pass beyond my Hall, you must defeat me in a game of skill! Control your king when you are ready to begin...
[1419056002] = [===[Щоб пройти повз мою залу, ви маєте здолати мене в грі на майстерність! Торкніться короля, коли будете готові почати...]===],
},
[17827] = { -- Claw
-- How embarrassing to be taken as a pet by a hunter!
--
-- I owe you my life, but please, trouble yourself no longer with my welfare. Now that you've freed me from Musel'ek, I'll be able to find my way out. Maybe I'll pick up Rayge along the way.
[3146544543] = [===[Як принизливо бути ручною твариною якогось мисливця!

Я завдячую тобі життям, але не переймайся за мене. Тепер, коли ти звільнив мене від Мусел'ека, я й сам знайду дорогу назад. Може, ще й підхоплю Райджа по дорозі.]===],
},
[17852] = { -- Thrall
-- I am with you, Thrall.
[1582545310] = [===[Я з тобою, Тралле.]===],
-- Lady Proudmoore's forces have bled to delay Archimonde and his Burning Legion, and now this grim task falls to us. Are you ready to stand with me against the onslaught?
[1791273726] = [===[Сили леді Праудмур проливали кров, стримуючи Архімонда та його Палаючий Легіон, і тепер це завдання лягає на нас. Ти {стать:готовий:готова} стояти зі мною проти цього натиску?]===],
-- May the spirits be with you.
[1787114019] = [===[Нехай духи бережуть тебе.]===],
-- Outstanding! Kaz'rogal's death cry should strike fear into the core of the Burning Legion. They now know the power your forces possess, so expect the worst the Legion can offer.
[322899723] = [===[Неймовірно! Передсмертний крик Каз'роґала мав вразити навіть війська Палаючого Легіону. Тепер вони знають, на що здатне наше військо, тож чекай найгіршого, що може запропонувати Легіон.]===],
-- Outstanding! Killing a Pit Lord such as Azgalor is no small feat, my friend. If we had more time, I would love to hear the story of you and your companions. Archimonde will not give us that pleasure, however. My scouts have already reported that the Legion is amassing an immense force outside our camp, and Archimonde is very close to the World Tree. We are evacuating with the help of Lady Proudmoore. You should head to the World Tree at once. The fate of our world is still undecided.
[3958017961] = [===[Неймовірно! Убити володаря безодні на кшталт Азґалора — це не аби що. Якби в нас було більше часу, я залюбки послухав би історію про тебе й твоїх супутників. Та Архімонд не дасть нам перепочинку. Мої розвідники доповіли, що Легіон збирає величезні сили біля нашого табору, а Архімонд зовсім близько до Світового Дерева. Ми відступимо за допомогою леді Праудмур. Тобі слід негайно вирушити до Світового Дерева. Доля нашого світу ще не вирішена.]===],
-- The Burning Legion presses us hard, but our defenses hold. Every moment we keep Archimonde away from the World Tree brings us closer to victory.
[2914616063] = [===[Палаючий Легіон тисне на нас щосили, але наша оборона тримається. Кожна мить, поки ми стримуємо Архімонда від Світового Дерева, наближає нас до перемоги.]===],
-- Then let the Legion do their worst!
[3820951068] = [===[Тоді нехай Легіон покаже все, на що здатний!]===],
-- Until we meet again, Thrall.
[494422791] = [===[До нових зустрічей, Тралле.]===],
-- We have nothing to fear.
[3778471281] = [===[Нам нема чого боятися.]===],
},
[17876] = { -- Thrall
-- I will do no such thing. I simply cannot leave Taretha in danger while I run off into the mountains. I am no coward. Now, where is she?
[569161794] = [===[Я не можу піти. Я не можу просто лишити Таретту в небезпеці й втекти в гори. Я не боягуз. Кажи, де вона?]===],
-- I'm glad Taretha is alive. We now must find a way to free her from her magical bindings.
[4174243572] = [===[Я радий, що Тарета жива. Тепер ми маємо якось звільнити її від магічних пут.]===],
-- Taretha cannot see you, Thrall.
[4185996467] = [===[Тарета поки не зможе прийти, Тралле.]===],
-- Tarren Mill lies beyond these trees. The commotion at Durnholde should give us a little time to find Taretha before the entire countryside is flooded with human soldiers. Let's check the nearby barn, then head into town.
[3685946611] = [===[Тарренський Млин прямо за цими деревами. Метушня в Дарнгольді має дати нам трохи часу, щоб знайти Тарету, перш ніж солдати заполонять усю округу. Оглянемо той хлів, а тоді вирушимо до міста.]===],
-- Tarren Mill.
[3964443608] = [===[В Тарренському Млині.]===],
-- Thank you friends, I owe my freedom to you. Where is Taretha? I hoped to see her one last time and thank her before leaving into the mountains.
[2191648695] = [===[Дякую, друзі, я завдячую вам своєю свободою. Де Тарета? Я сподівався ще раз побачити її й віддячити, перш ніж піти в гори.]===],
-- The situation is rather complicated, Thrall. It would be best for you to head into the mountains now, before more of Blackmoore's men show up. We'll make sure Taretha is safe.
[4177929075] = [===[Ситуація доволі складна, Тралле. Тобі краще вирушити в гори зараз, поки не прийшло ще більше людей Блекмура. Ми подбаємо, щоб Тарета була в безпеці.]===],
-- We are ready to get you out of here, Thrall. Let's go!
[3858421082] = [===[Ми готові вивести тебе звідси, Тралле. Ходімо!]===],
-- We're ready, Thrall.
[3231349268] = [===[Ми готові, Тралле.]===],
-- What do you mean by this? Is Taretha in danger?
[3159376543] = [===[Що сталося? Тареті щось загрожує?]===],
-- Who are you? Just leave me be.
[3866901876] = [===[Хто ти? Просто дай мені спокій.]===],
},
[17885] = { -- Earthbinder Rayge
-- Thank goodness for you! Claw and I were investigating this place when we were jumped by Swamplord Musel'ek. He can control animals, even druids!
--
-- Unfortunately, Claw was caught in bear form at the time, and is now the swamplord's pet. I don't dare change into cat form or he'll get me too!
--
-- I'm afraid you'll have to fight Claw in order to save him. Just keep heading west; you can't miss him.
[471357637] = [===[Яке щастя, що ти тут! Ми з Кігтем досліджували це місце, коли на нас накинувся володар боліт Мусел'ек. Він уміє підкоряти тварин, навіть друїдів!

На жаль, Кіготь саме тоді був у подобі ведмедя, і тепер він — ручний звір володаря боліт. Я не ризикну битися в подобі кота, бо тоді він і мене підкорить!

Боюся, що тобі доведеться перемогти Кігтя, щоб визволити його. Просто йди далі — ти не проминеш їх.]===],
},
[17890] = { -- Weeder Greenthumb
-- Here lie the remains of Weeder Greenthumb, one of Watcher Jhang's druid companions. By all appearances he was killed quick and clean while trying to make his escape from the Slave Pens.
[2988504336] = [===[Тут лежать рештки травника Зеленопала, одного з товаришів наглядачки Джанг. Судячи з усього, його вбили під час спроби втечі із Загонів рабів.]===],
},
[17893] = { -- Naturalist Bite
-- Alright, Bite, I'll let you out.
[3820726957] = [===[Гаразд, Кусе, я тебе випущу.]===],
-- I almost made it!
--
-- I came in here to prove the existence of Quagmirran, that most mythical of fungal giants. I got my wish, sort of.
--
-- You must let me free! In return I will grant you a boon to help you to deal with Quagmirran.
[2884663809] = [===[Мені майже вдалось!

Я прийшов сюди, щоб довести існування Трясовуна, найміфічнішого з грибних велетнів. Моє бажання здійснилося... Ну, певною мірою.

Ти маєш звільнити мене! Натомість я дарую тобі благословення, яке допоможе тобі впоратися з Трясовуном.]===],
-- Naturalist, please grant me your boon.
[3342410959] = [===[Натуралісте, даруй мені своє благословення.]===],
-- Now that the rude interruption is over, as I was saying, Quagmirran is nearby!
--
-- As promised, I can fortify you with a magical boon that should aid you in your fight with him.
[3186562443] = [===[Як я вже казав, Трясовун десь неподалік!

Я можу надати тобі магічне благословення, яке допоможе в бою з ним.]===],
},
[18063] = { -- Garrosh
-- What is it that you want, <race>?
[511042405] = [===[Що ти хочеш, {раса:к}?]===],
["!code"] = {
["wtisitttyuwt.."] = 511042405,
},
},
[18141] = { -- Greatmother Geyah
-- <Greatmother Geyah laughs weakly.>
--
-- Of course not, dear. But it's not me that has to believe...
--
-- Garrosh can lead the Mag'har. He is strong and wise. All of the spirits approve of him. He just needs to believe in himself. He fears so much... He fears so deeply that if he lets himself go, his rage will consume him and all that would be near him.
[601419251] = [===[<Праматір Ґейя знесилено сміється.>

Звісно ж ні, {стать:любий:люба}. Але це не я маю вірити...

Ґаррош здатен очолити Маґ'харів. Він має силу та мудрість. Всі духи підтримують його. Йому лише бракує віри в себе. Він так боїться... Він так сильно боїться, що якщо дозволить собі розслабитися, його гнів може поглинути і його, і всіх, хто буде поруч з ним.]===],
-- <Greatmother Geyah nods, accepting your answer.>
--
-- I can no longer fight the spirits, <name>. My time has long since passed. Once again, I must thank you for all that you have done. While Garrosh may be unmovable, many of my people have been lifted by your accomplishments. They are now willing to fight for our rights as a united clan.
[2473103482] = [===[<Праматір Ґейя киває вам у відповідь.>

Я більше не можу боротися з духами, {ім'я:к}. Мій час давно минув. Ще раз дякую тобі за все, що ти {стать:зробив:зробила}. Хоча Ґаррош, можливо, і непохитний, багато хто з мого народу надихнувся твоїми досягненнями. Тепер вони готові боротися за наш клан.]===],
-- <Greatmother Geyah nods.>
--
-- Did you know my son?
[1408561307] = [===[<Праматір Гейя киває.>

Ти {стать:знав:знала} мого сина?]===],
-- <Greatmother Geyah smiles at you.>
--
-- You remind me of my son, <name>.
--
-- He was an immovable mountain: A pillar of strength and honor.
--
-- <Geyah's eyes well up with tears.>
--
-- He sacrificed himself so that we could survive. So that generations of orcs after him could be born into a world without the blood curse... Without Gul'dan and his dark Horde...
--
-- <Geyah stares into the distance, lost in thought.>
--
-- Oh Durotan, how I wish you could be here. Your people so desperately need you...
[3359971584] = [===[<Праматір Ґейя усміхається вам.>

Ти нагадуєш мені мого сина, {ім'я:к}.

Він був незрушною горою. Стовпом сили та честі.

<Очі Ґейї наповнюються сльозами..>

Він пожертвував собою, щоб ми могли вижити. Щоб наступні покоління орків могли народитися у світі без кровного прокляття... Без Ґул'дана і його темної Орди...

<Ґейя дивиться вдалину, заглибившись у думки.>

Ох, Дуротане, якби тільки ти міг бути тут. Твій народ так потребує тебе...]===],
-- <Greatmother Geyah smiles.>
--
-- I am old. It is my time. When I pass, my spirit will move on to the spirit realm. It is there that I will stand with my ancestors. It is there that we will watch over our people.
--
-- When Garad was alive Mother Kashur's duty was the same as my duty now.
[1401478464] = [===[<Праматір Ґейя усміхається.>

Я уже стара. Мій час прийшов. Коли я помру, моя душа перейде в царство духів. Там я буду разом із предками. Там ми будемо пильнувати за нашим народом.

Коли Ґарад був живий, обов'язок матері Кашур був таким самим, як і мій зараз.]===],
-- <Greatmother Geyah smiles.>
--
-- I am old. When I pass, my spirit will move on to the spirit realm. It is there that I will stand with my ancestors. It is there that we will watch over our people.
--
-- When Garad was alive, Mother Kashur's duty was the same as my duty now.
[2993124967] = [===[<Праматір Ґейя усміхається.>

Я уже стара. Коли я помру, моя душа перейде в царство духів. Там я буду разом із предками. Там ми будемо пильнувати за нашим народом.

Коли Ґарад був живий, обов'язок матері Кашур був таким самим, як і мій зараз.]===],
-- <Greatmother Geyah's violet eyes lock onto yours.>
--
-- Yes...
[2802313280] = [===[<Праматір Ґейя пильно дивиться вам у вічі.>

Так?..]===],
-- <Tears stream down Greatmother Geyah's face.>
--
-- I... I... Durotan survived to have a child? The child Draka told me of before they left... It was their greatest fear... To raise a child in this world. On the other side of that gate was their only hope. I dared not tell Durotan, but secretly, I begged the spirits to watch over them - to protect their child and to give them strength.
--
-- I... I must see my grandchild. I must see him. Please, I am too weak. You must tell him. Before I leave this world...
[963507686] = [===[<По щоках праматері Ґейї течуть сльози.>

Я... Я... Дуротан вижив, і в нього народилася дитина? Дитина, про яку мені казала Драка перед тим, як вони пішли... То був їхній найбільший страх... Виховувати дитину в цьому світі. По інший бік брами була їхня єдина надія. Я не наважилась сказати про це Дуротану, але потайки я благала духів наглядати за ними... захищати їхню дитину і дарувати їй силу.

Я... Я маю побачити свого онука. Я маю побачити його. Будь ласка, я занадто слабка. Ти маєш сказати йому. Перш ніж я покину цей світ...]===],
-- Do you believe that?
[2718438949] = [===[Ви в це вірите?]===],
-- Garrosh is beyond redemption, Greatmother. I fear that in helping the Mag'har, I have convinced Garrosh that he is unfit to lead.
[2218319486] = [===[Ґаррошу вже немає порятунку, праматір. Боюся, що, допомагаючи Маґ'харам, я {стать:переконав:переконала} Ґарроша в тому, що він не гідний бути лідером.]===],
-- Greatmother, I never had the honor. Durotan died long before my time, but his heroics are known to all on my world. The orcs of Azeroth reside in a place known as Durotar, named after your son. And... <You take a moment to breathe and think through what you are about to tell the Greatmother.>
[3200651922] = [===[Ні, праматір, мені не випала така честь. Дуротан помер задовго до мого народження, але його героїзм відомий усім у моєму світі. Орки Азероту мешкають у місці, відомому як Дуротар, названому на честь вашого сина. І... <Ви робите паузу, щоб перевести подих і обдумати те, що збираєтеся сказати праматері.>]===],
-- Greatmother, you are the mother of Durotan?
[213614705] = [===[Праматір, ви мати Дуротана?]===],
-- Hello, Greatmother. Garrosh told me that you wanted to speak with me.
[10272067] = [===[ВІтаю, праматір. Ґаррош сказав мені, що ви хотіли поговорити зі мною.]===],
-- Hello, dear. I am Geyah, matron of the Mag'har.
--
-- <Greatmother Geyah coughs.>
--
-- If you are here, it would be safe to assume that the portal has opened. Most of the orcs here were too young or too sick to remember the Dark Portal.
--
-- <Greatmother Geyah points to the orcs around her.>
--
-- Many of them were orphans or would soon become orphans. Aye, Blackhand would have it no other way. Keep the sick from the healthy. Only the strong would survive... Or so they say.
[668698122] = [===[Привіт, {стать:любий:люба}. Я — Ґейя, матрона Маг'харів.

<Праматір Ґейя кашляє.>

Якщо ти тут, можна з упевненістю припустити, що портал знову відкритий. Більшість тутешніх орків були занадто молодими або занадто хворими, щоб пам'ятати відкриття Темного Порталу.

<Праматір Ґейя вказує на орків навколо себе.>

Багато з них були сиротами або незабаром мали ними стати. Так, Чорнорук би не допустив іншого. Відокремити хворих від здорових. Лише сильні повинні вижити... Так тоді казали.]===],
-- Hello, young <race>.
[3054648004] = [===[Здрастуй, {стать:юний:юна} {раса:к}.]===],
-- I have done all that I could, Greatmother. I thank you for your kind words.
[626702165] = [===[Я {стать:зробив:зробила} все, що {стать:міг:могла}, праматір. Дякую за ваші добрі слова.]===],
-- I will return to Azeroth at once, Greatmother.
[2020116693] = [===[Я негайно повернуся до Азероту, праматір.]===],
-- I wish I knew, dear. He will not listen to you nor will he listen to me. In truth, it is why I am still here. It is why I have not left with Mother Kashur. He must find his heart. Our people will not survive through the winter without leadership.
[1907741357] = [===[Хотіла б я знати, {стать:любий:люба}. Він не слухатиме ні тебе, ні мене. Власне, саме тому я досі тут. Саме тому я не пішла разом із матір'ю Кашур. Він повинен віднайти своє серце. Наш народ не переживе зиму без лідера.]===],
-- Is there anything I can do for you, Greatmother?
[2751971330] = [===[Чи є щось, що я можу зробити для вас, праматір?]===],
-- It is my Warchief, Greatmother. The leader of my people from my world. He... He is the son of Durotan. He is your grandchild.
[551700603] = [===[Це мій вождь, праматір. Лідер мого народу з мого світу. Він... Він син Дуротана. Він ваш онук.]===],
-- It is my warchief, Greatmother. The leader of my people. From my world. He... He is the son of Durotan. He is your grandchild.
[3353761351] = [===[Це мій вождь, праматір. Лідер мого народу з мого світу. Він... Він син Дуротана. Він ваш онук.]===],
-- Left? How can you choose to leave?
[2362491811] = [===[Пішла? Як ви можете піти?]===],
-- The duty of a clan mother is to listen. To listen to the wind and the water and the fire and the earth. To gather information for her clan in the way others gather furs to stay warm. It is the spirits that I commune with... In my dreams, Mother Kashur speaks to me like the spirits that spoke to her once... When I pass, I will speak to Drakia and Celestine in this manner.
--
-- <Greatmother Geyah smiles.>
[2266065314] = [===[Обов'язок матері клану — слухати. Слухати вітер, воду, вогонь і землю. Збирати інформацію для свого клану так, як інші збирають хутра, щоб зігрітися. Я спілкуюся з духами... У моїх снах мати Кашур розмовляє зі мною так само як колись з нею розмовляли духи… Коли я помру, я буду таким же чином розмовляти з Дракією і Целестіною.

<Праматір Ґейя усміхається.>]===],
-- They have grown up here. We kept them safe from harm. We did the best that we could in nursing them back to health. Many perished but many, many more grew strong. Like Garrosh...
--
-- <Greatmother Geyah sighs.>
--
-- He has lost his heart, you know. He tells me that I am his balance. That without me, the blood lust that consumed his father and ultimately cursed our people would take him over.
[524179417] = [===[Вони виросли тут. Ми оберігали їх від небезпеки. Ми робили все, що могли, аби вилікувати їх. Багато хто загинув, але ще більше стали сильними. Як Ґаррош...

<Праматір Ґейя зітхає.>

Він втратив своє серце, знаєш. Він каже мені, що я є його рівновагою. Що без мене жага крові, яка поглинула його батька та врешті прокляла наш народ, захопить і його.]===],
-- They have grown up here. We kept them safe from harm. We did the best that we could in nursing them back to health. Many perished but many, many more grew strong. Like Garrosh...
--
-- <Greatmother Geyah sighs.>
--
-- He has lost his heart, you know. He tells me that I am his balance. That without me, the bloodlust that consumed his father and ultimately cursed our people would take him over.
[1736851125] = [===[Вони виросли тут. Ми оберігали їх від небезпеки. Ми робили все, що могли, аби вилікувати їх. Багато хто загинув, але ще більше стали сильними. Як Ґаррош...

<Праматір Ґейя зітхає.>

Він втратив своє серце, знаєш. Він каже мені, що я є його рівновагою. Що без мене жага крові, яка поглинула його батька та врешті прокляла наш народ, захопить і його.]===],
-- What can be done? I have tried many different things. I have done my best to help the people of Nagrand. Each time I have approached Garrosh, he has dismissed me.
[2307592632] = [===[Що можна зробити? Я {стать:спробував:спробувала} багато різних речей. Я {стать:зробив:зробила} все можливе, щоб допомогти жителям Наґранда. Щоразу, коли я {стать:звертався:зверталася} до Ґарроша, він відмовлявся мене слухати.]===],
-- What did Garrosh tell you, <name>?
[2954981535] = [===[Що сказав тобі Ґаррош, {ім'я:к}?]===],
-- What is this duty?
[2489747424] = [===[Що це за обов'язок?]===],
-- You raised all of the orcs here, Greatmother?
[2499541539] = [===[Ви виростили всіх тутешніх орків?]===],
-- You raised all the orcs here, Greatmother?
[3380192431] = [===[Ви виростили всіх тутешніх орків?]===],
["!code"] = {
["grghnsagyrarcnnolrfttess.-mytehslgsepdoean"] = 2473103482,
["grghssatyuyurdmeofmysn.-hewsaniemnprofshad"] = 3359971584,
["hoyg.."] = 3054648004,
["wtddghtlyu.-"] = 2954981535,
},
},
[18166] = { -- Khadgar
-- <Khadgar grins to himself>
--
-- I convinced A'dal and his brethren to return here with me. I believe that only their power can drive the Legion from this universe. But as you will no doubt find - their power must first live in our hearts.
--
-- To combat the darkness, we must become beacons of their eternal Light.
[237784392] = [===[<Кадґар усміхається сам до себе.>

Я переконав А'дала та інших наару повернутися сюди зі мною. Я вірю, що лише їхня сила здатна вигнати Легіон із цього світу. Та, як ти й {стать:сам:сама} переконаєшся, — їхня сила спершу має оселитися в наших серцях.

Щоб протистояти темряві, ми самі маємо стати маяками їхнього вічного Світла.]===],
-- Go on, please.
[3050890991] = [===[Прошу, продовжуй.]===],
-- I am Khadgar, former apprentice to the fallen Guardian, Medivh. I'm sure you've heard his name before.
--
-- It was I who discovered that Medivh had been possessed by the Evil One, Sargeras - and that he had opened the Dark Portal between this world and Azeroth. Though I honored my Master, I was forced to slay him and put his tortured soul to rest.
[1192462097] = [===[Я Кадґар, колишній учень сумнозвісного Вартівника, Медіва. Певен, ти вже {стать:чув:чула} це ім'я.

Це я виявив, що Медівом заволоділо зло, Сарґерас, і що саме він відкрив Темний Портал між цим світом та Азеротом. Хоч я й шанував свого наставника, мені довелося вбити його й принести спокій його змученій душі.]===],
-- I fought alongside Lord Anduin Lothar as we drove the Horde from our lands on Azeroth. As the heir of Medivh's legacy, I could do no less.
--
-- When the call finally came to invade this grim world - and put an end to the orcs' evil forever - I stepped forward along with my friends Turalyon, Alleria, Danath and Kurdran.
[3592739027] = [===[Я бився пліч-о-пліч із лордом Андуїном Лотаром, коли ми виганяли Орду з наших земель на Азероті. Як спадкоємець справи Медіва, я не міг чинити інакше.

Коли нарешті пролунав заклик вторгнутися в цей похмурий світ — і назавжди покласти край злу орків, — я виступив уперед разом зі своїми друзями Тураліоном, Аллерією, Данатом і Курдраном.]===],
-- I see.
[143907485] = [===[Продовжуй.]===],
-- I've heard your name spoken only in whispers, mage. Who are you?
[3020638981] = [===[Я не раз {стать:чув:чула} твоє ім'я, магу. Хто ти?]===],
-- My comrades and I called ourselves the Sons of Lothar - in honor of the greatest, most selfless man we ever knew. We gave our all to defeat Ner'zhul and end his madness.
--
-- As this doomed world fell apart around us, we shattered the Dark Portal to prevent any further harm befalling our beloved Azeroth.
[1635771567] = [===[Ми назвали себе Синами Лотара — на честь найвеличнішої, найшляхетнішої людини, яку ми знали. Ми відчайдушно билися, щоб здолати Нер'зула й покласти край його безумству.

Коли цей приречений світ почав руйнуватись, ми знищили Темний Портал, щоб запобігти подальшій шкоді Азероту.]===],
-- The naaru are wise beyond our understanding. I've learned more from A'dal in the last five months than all the years I spent in the libraries of Dalaran.
[333724075] = [===[Наару мудріші, ніж ми здатні осягнути. За останні п'ять місяців я навчився від А'дала більше, ніж за всі роки, проведені в бібліотеках Даларана.]===],
-- There was something else I wanted to ask you.
[2072845323] = [===[Я {стать:хотів:хотіла} запитати ще дещо.]===],
-- Trapped in this broken wasteland, we did our best to survive. Over time we sensed that a new evil was closing in around us from the Twisting Nether. More foul than the dark orcs - it was the Burning Legion itself that sought to take hold of this... Outland.
[3628931464] = [===[Замкнені в цій понівеченій пустці, ми робили все можливе, щоб вижити. Із часом ми відчули, як із Підсвітньої Крутоверті насувається нове зло. Гірше за темних орків — сам Палаючий Легіон прагнув заволодіти цим... Позамежжям.]===],
-- What did you do then?
[1287418806] = [===[Що було далі?]===],
-- What happened next?
[280265843] = [===[Що сталося потім?]===],
-- While my comrades held the line against the encroaching darkness, I used my magic to reach out into the Great Dark Beyond. There, I sensed beings of immense Light - of unfathomable purity.
--
-- It was A'dal and his naaru I had found. It was nothing short of a... miracle.
[2758076725] = [===[Поки мої побратими стримували наступ темряви, я спрямував свою магію у Велику Позамежну Темряву. Там я відчув присутність істот безмежного Світла — незбагненної чистоти.

Я знайшов А'дала і його наару. Це було справжнє... диво.]===],
},
[18180] = { -- Hemet Nesingwary
-- Hemet Nesingwary, what are you doing here in the Outland?
[1236741140] = [===[Гемет Ернінґвей? Що ти робиш у Позамежжі?]===],
-- Keep a sharp eye, <class>. You never know when some beastie is stalking you instead of the other way around.
[2716658081] = [===[Будь насторожі, {клас:к}. Ніколи не знаєш, коли на тебе полює якесь чудовисько.]===],
-- Listen lad. I left the expedition in the capable hands of me son, Junior. When you've stalked the finest game in all of Azeroth you start to itch for something more.
--
-- And have you seen the size of the beasties here?!
--
-- I'm here hunting the most dangerous prey you'll ever lay your eyes on. I mean to bag myself Tusker and take her heart as my trophy!
[2713948826] = [===[Слухай, {стать:приятелю:приятелько}. Я залишив експедицію в надійних руках свого сина, Гемета молодшенького. Коли ти полював на найкращу дичину по всьому Азероту, починаєш прагнути чогось більшого.

А ти {стать:бачив:бачила} розміри цих звірів?!

Я тут полюю на найнебезпечнішу здобич, яку ти коли-небудь {стать:бачив:бачила}. Я маю на меті вполювати Бивню та забрати її серце як трофей!]===],
["!code"] = {
["kpspee..yunrkwwnsebeissgyuidofteorwyad"] = 2716658081,
},
},
[18200] = { -- Shado Fitz Farstrider
-- Greetings, <class>. You seek to push yourself to the limits of your hunting prowess? Look no further.
--
-- Hemet Nesingwary has assembled the finest expedition the remnant of this world has ever known. Join us on safari if you dare.
[212988032] = [===[Вітаю, {клас:к}. Ти прагнеш випробувати межі своїх мисливських здібностей? Тоді ти {стать:прийшов:прийшла} куди треба.

Гемет Ернінґвей зібрав найкращу експедицію, яку коли-небудь бачив цей світ. Приєднуйся до нас на сафарі, якщо наважишся.]===],
["!code"] = {
