[3518579447] = [===[Я ВІЛЬНО ВОЛОДІЮ БІЛЬШ НІЖ ДВОМА МОВАМИ: ДВОРФІЙСЬКОЮ, ГНОМСЬКОЮ ТА МОВОЮ ЛЮДЕЙ. АЛЕ Я НЕ РОЗУМІЮ, ЩО ВИ ГОВОРИТЕ!

